/* MIT. A synthetic local service is required; never connects to business APIs. */
(()=>{'use strict';const $=s=>document.querySelector(s),ids=['A-51','A-52'];let saved;try{saved=JSON.parse(localStorage.getItem('oil-ui-demo:order'))}catch{}const session=saved?.session||crypto.randomUUID(),state={session,accepted:[],unknown:false,key:crypto.randomUUID(),...saved};let busy=false,validation=0;
const fields=['warehouse','contact','qty-A-51','qty-A-52','window'];fields.forEach(id=>{if(state[id]!==undefined)$('#'+id).value=state[id]});
const persist=()=>{fields.forEach(id=>state[id]=$('#'+id).value);localStorage.setItem('oil-ui-demo:order',JSON.stringify(state))};
const api=async(path,options={})=>{const r=await fetch('/api/'+path,{...options,headers:{'Content-Type':'application/json','X-Demo-Session':session,...options.headers}});const data=await r.json();if(!r.ok)throw Object.assign(Error(data.message||'服务请求失败'),{status:r.status,data});return data};
function feedback(text){$('#result').textContent=text}
function errors(list){$('#errors h2').textContent=state.accepted.length?'已接纳 '+state.accepted.length+' 项，不会重发；请调整未完成项':'请检查后继续';$('#error-list').replaceChildren();$('#errors').hidden=!list.length;['warehouse','contact',...ids.map(id=>'qty-'+id)].forEach(id=>$('#'+id).removeAttribute('aria-invalid'));['contact-error',...ids.map(id=>'error-'+id)].forEach(id=>$('#'+id).textContent='');for(const [id,text] of list){$('#'+id).setAttribute('aria-invalid','true');let li=document.createElement('li'),a=document.createElement('a');a.href='#'+id;a.textContent=text;a.onclick=e=>{e.preventDefault();$('#'+id).focus()};li.append(a);$('#error-list').append(li);let e=$('#'+(id==='contact'?'contact-error':id.startsWith('qty-')?'error-'+id.slice(4):'warehouse-note'));e.textContent=text;e.classList.add('error')}if(list.length)$('#errors').focus()}
function sync(){ids.forEach(id=>{const done=state.accepted.includes(id);$('#qty-'+id).disabled=done||state.unknown||busy;$('#state-'+id).textContent=done?'已接纳 · 不会重发':state.unknown?'结果待核实':'待提交'});$('#submit').disabled=busy||state.unknown||state.accepted.length===ids.length;$('#submit').textContent=busy?'正在提交…':state.accepted.length?'提交未完成项':'确认配送';$('#check').hidden=!state.unknown;$('#check').disabled=busy;$('#check').classList.toggle('primary',state.unknown);$('#submit').classList.toggle('primary',!state.unknown);const actions=$('#submit').parentElement;if(state.unknown)actions.prepend($('#check'));else actions.append($('#check'));$('#contact').disabled=busy||state.unknown;$('#warehouse').disabled=busy||state.unknown;persist()}
async function counters(){try{const c=await api('counters');$('#receipt').replaceChildren(...[['提交请求',c.requests],['后端写入（诊断）',c.writes],['核实请求',c.readbacks],['后端接纳记录（诊断）',c.accepted.join('、')||'无']].map(([k,v])=>{const d=document.createElement('div');d.textContent=k+'：'+v;return d}));$('#receipt').dataset.counts=JSON.stringify(c);$('#connection').textContent='已连接本地隔离服务'}catch{$('#connection').textContent='无法连接服务；保留草稿，不伪造成功'}}
async function validateWarehouse(){const value=$('#warehouse').value.trim(),seq=++validation;$('#warehouse-note').className='muted';if(!value){$('#warehouse-note').textContent='请填写出货仓库';return false}$('#warehouse-note').textContent='正在检查…';try{const r=await api('warehouse?name='+encodeURIComponent(value));if(seq!==validation||value!==$('#warehouse').value.trim())return false;$('#warehouse-note').textContent=r.available?'仓库可用':'该仓库当前停用，请调整';$('#warehouse-note').className=r.available?'muted':'error';return r.available}catch{if(seq===validation)$('#warehouse-note').textContent='仓库检查失败，请重试；尚未提交';return false}}
$('#warehouse').oninput=()=>{validation++;$('#warehouse-note').textContent='仓库信息已更改，尚未检查';persist()};$('#warehouse').onblur=validateWarehouse;fields.filter(x=>x!=='warehouse').forEach(id=>$('#'+id).addEventListener('input',persist));
$('#order').onsubmit=async e=>{e.preventDefault();if(busy||state.unknown)return;let list=[];if(!$('#warehouse').value.trim())list.push(['warehouse','请填写出货仓库']);if(!$('#contact').validity.valid||!$('#contact').value.trim())list.push(['contact','请填写有效的接收邮箱']);ids.filter(id=>!state.accepted.includes(id)).forEach(id=>{const v=Number($('#qty-'+id).value);if(!Number.isInteger(v)||v<1||v>99)list.push(['qty-'+id,id+' 数量须为 1–99 的整数'])});errors(list);if(list.length)return;busy=true;sync();const valid=await validateWarehouse();busy=false;sync();if(!valid){errors([['warehouse',$('#warehouse-note').textContent]]);return}$('#confirm').showModal()};
$('#cancel-confirm').onclick=()=>$('#confirm').close();$('#confirm').addEventListener('close',()=>{if(!busy)$('#submit').focus()});
$('#send').onclick=async()=>{if(busy||state.unknown)return;busy=true;$('#confirm').close();sync();errors([]);const payload={key:state.key,warehouse:$('#warehouse').value,contact:$('#contact').value,window:$('#window').value,items:ids.filter(id=>!state.accepted.includes(id)).map(id=>({id,qty:Number($('#qty-'+id).value)})),scenario:$('#scenario').value};try{const r=await api('orders',{method:'POST',body:JSON.stringify(payload)});state.accepted=[...new Set([...state.accepted,...r.accepted])];if(r.status==='unknown'){state.unknown=true;feedback('提交结果待核实 · '+r.requestId+'。先核实，不自动重发。')}else if(r.errors&&Object.keys(r.errors).length){state.key=crypto.randomUUID();errors(Object.entries(r.errors).map(([id,text])=>['qty-'+id,id+'：'+text]));feedback('部分成功。已接纳项保留，请只更正未完成项。')}else{feedback('服务器已确认：配送申请已接纳。')}}catch(e){if([403,422,503].includes(e.status)){feedback(e.message+'；输入与草稿已保留。');state.key=crypto.randomUUID()}else{state.unknown=true;feedback('连接中断，提交结果待核实。请先查单，不自动重发。')}}finally{busy=false;sync();await counters();if(state.unknown)$('#check').focus();else if(!$('#errors').hidden)$('#errors').focus()}};
$('#check').onclick=async()=>{if(busy)return;busy=true;sync();try{const r=await api('orders?key='+encodeURIComponent(state.key));if(r.status==='pending'){feedback('核实结果：仍在处理中，尚不能判定成功。可稍后再次核实。')}else if(r.status==='not_found'){state.unknown=false;state.key=crypto.randomUUID();feedback('服务端明确未找到本次申请。草稿保留，可再次确认提交。')}else{state.accepted=[...new Set([...state.accepted,...r.accepted])];state.unknown=false;feedback('已核实：申请已接纳；未重发提交。')}}catch{feedback('核实失败，仍为待核实；输入保留。')}finally{busy=false;sync();await counters()}};
$('#save-draft').onclick=()=>{persist();feedback(state.unknown?'本地草稿已保存，提交结果仍待核实。':'本地草稿已保存，尚不代表提交成功。')};
const trigger=$('#window-trigger'),popover=$('#window-popover');function closeWindow(){popover.hidden=true;trigger.setAttribute('aria-expanded','false');trigger.textContent='配送窗口：'+$('#window').value;persist();trigger.focus()}trigger.onclick=()=>{popover.hidden=!popover.hidden;trigger.setAttribute('aria-expanded',String(!popover.hidden));if(!popover.hidden)$('#window').focus()};$('#window-close').onclick=closeWindow;popover.onkeydown=e=>{if(e.key==='Escape'){e.preventDefault();e.stopPropagation();closeWindow()}};
if(state.unknown)feedback('已恢复本地草稿；上次提交结果待核实，请先查单。');else if(saved)feedback('已恢复本地草稿；已接纳项不会重发。');sync();counters();})();
